ALTER TABLE hr_person_profile ADD COLUMN IF NOT EXISTS position_id CHAR(36) NULL;
CREATE INDEX IF NOT EXISTS hr_person_profile_position_index ON hr_person_profile (position_id);
UPDATE hr_person_profile pr JOIN person p ON p.id = pr.person_id JOIN hr_position pos ON pos.name = p.position_title SET pr.position_id = pos.id WHERE pr.position_id IS NULL;
ALTER TABLE hr_person_profile ADD CONSTRAINT hr_person_profile_position_fk FOREIGN KEY IF NOT EXISTS (position_id) REFERENCES hr_position(id);
